(() => { const body=document.getElementById('supplier-bill-lines'), add=document.getElementById('add-supplier-line'), total=document.getElementById('supplier-bill-total'); if(!body||!add||!total)return; const units=['item','piece','kg','bag','litre','tray','crate','animal','bird','chick','service'], breeds=@json($poultryBreedOptions); const breedOptions=()=>`<option value="">Not a poultry purchase</option>${breeds.map(breed=>`<option value="${breed.id}">${breed.name}</option>`).join('')}`; const refresh=()=>{total.textContent=[...body.querySelectorAll('.supplier-line-amount')].reduce((sum,input)=>sum+(parseFloat(input.value)||0),0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});body.querySelectorAll('.supplier-line-remove').forEach(button=>button.disabled=body.rows.length===1)}; const bind=row=>{row.querySelector('.supplier-line-amount').addEventListener('input',refresh);row.querySelector('.supplier-line-remove').addEventListener('click',()=>{if(body.rows.length>1){row.remove();refresh()}})}; body.querySelectorAll('tr').forEach(bind); const pick=document.getElementById('feed-delivery-field');const feeds=pick?JSON.parse(pick.dataset.feeds):[];const syncPick=()=>{if(!pick)return;pick.hidden=![...body.querySelectorAll('input[name$="[item_name]"]')].some(i=>feeds.includes(i.value.trim().toLowerCase()));};body.addEventListener('input',syncPick);syncPick();add.addEventListener('click',()=>{const index=body.rows.length;const row=document.createElement('tr');row.innerHTML=`<td><input name="lines[${index}][item_name]" list="supplied-item-list" placeholder="Choose or type item" required></td><td><input name="lines[${index}][quantity]" type="number" min="0.01" step="0.01" required></td><td><select name="lines[${index}][unit]">${units.map(unit=>`<option value="${unit}"${unit==='kg'?' selected':''}>${unit[0].toUpperCase()+unit.slice(1)}</option>`).join('')}</select></td><td><select name="lines[${index}][breed_id]">${breedOptions()}</select></td><td><input class="supplier-line-amount" name="lines[${index}][amount]" type="number" min="0.01" step="0.01" required></td><td><button class="btn btn--quiet supplier-line-remove" type="button">Remove</button></td>`;body.appendChild(row);bind(row);refresh()});refresh() })();
</script>
